DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `cong_tien_hu_game_bai`(IN p_pot_name NVARCHAR(45),
IN p_value_pot BIGINT(20),
IN p_value_pot_system BIGINT(20))
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION ROLLBACK;
  DECLARE EXIT HANDLER FOR SQLWARNING ROLLBACK;
  START TRANSACTION;
    UPDATE hu_game_bai SET `value` = p_value_pot WHERE `pot_name` = p_pot_name;
    UPDATE hu_game_bai SET `value` = p_value_pot_system WHERE `pot_name` = 'Vinplay';
    COMMIT;
END ;;
DELIMITER ;
