CREATE DEFINER=`root`@`%` PROCEDURE `tx_get_lich_su_giao_dich_md5`(IN nickname VARCHAR(45),
    IN page_number INT,
    IN money_type TINYINT(4))
BEGIN
  declare
num_start int;
    declare
num_end int;
    set
num_start = (page_number - 1) * 10;
    set
num_end = page_number * 10;
SELECT tran_tx.reference_id,
       tran_tx.user_id,
       tran_tx.user_name,
       tran_tx.bet_value,
       tran_tx.bet_side,
       tran_tx.total_prize,
       tran_tx.total_refund,
       tran_tx.`timestamp`,
       result_tx.dice1,
       result_tx.dice2,
       result_tx.dice3,
       tran_tx.total_exchange
FROM (SELECT *
      FROM transaction_tai_xiu_md5
      WHERE user_name = nickname
        AND transaction_tai_xiu_md5.money_type = money_type
      ORDER BY id DESC LIMIT num_start, num_end) as tran_tx
         INNER JOIN
     (SELECT * FROM result_tai_xiu_md5 WHERE result_tai_xiu_md5.money_type = money_type) as result_tx
     ON tran_tx.reference_id = result_tx.reference_id
ORDER BY tran_tx.reference_id DESC LIMIT 0, 10;
END ;;
DELIMITER ;
